shell_commands.command:
cd /testbed && patch -p0 <<'PATCH'
*** tokio/tests/sync_broadcast.rs.orig
--- tokio/tests/sync_broadcast.rs
***************
*** 523,525 ****
--- 523,575 ----
      assert_empty!(rx);
      assert_empty!(rx_resub);
  }
+
+ #[test]
+ fn resubscribe_closed_try_recv() {
+     for &capacity in &[1, 4] {
+         let (tx, rx) = broadcast::channel::<u32>(capacity);
+         drop(tx);
+
+         let mut rx_resub = rx.resubscribe();
+         drop(rx);
+
+         assert_closed!(rx_resub.try_recv());
+     }
+ }
+
+ #[test]
+ fn resubscribe_closed_recv() {
+     for &capacity in &[1, 4] {
+         let (tx, rx) = broadcast::channel::<u32>(capacity);
+         drop(tx);
+
+         let mut rx_resub = rx.resubscribe();
+         drop(rx);
+
+         let mut recv = task::spawn(rx_resub.recv());
+         assert!(is_closed(assert_ready_err!(recv.poll())));
+     }
+ }
+
+ #[test]
+ fn resubscribe_closed_with_pending_messages() {
+     for &capacity in &[1, 4] {
+         let (tx, mut rx) = broadcast::channel(capacity);
+         for value in 0..capacity {
+             assert_ok!(tx.send(value));
+         }
+         drop(tx);
+
+         let mut rx_resub = rx.resubscribe();
+         assert_closed!(rx_resub.try_recv());
+
+         for value in 0..capacity {
+             assert_eq!(assert_recv!(rx), value);
+         }
+         assert_closed!(rx.try_recv());
+     }
+ }
PATCH
cargo test --offline --test sync_broadcast --features full resubscribe_closed

